import java.util.ArrayList;
import java.util.List;

public class Main {
    public static void main(String[] args) {
        List<String> bowls = new ArrayList<>();
        bowls.add("{n1}");
        bowls.add("{n2}");
        System.out.println("最后一格是 " + bowls.get(bowls.size() - 1));
    }
}
